from __future__ import annotations
import html
import json
import math
from pathlib import Path
from datetime import datetime, timezone
import pandas as pd

DATA = Path('/app/benchmark/data.csv')
BRIEF = Path('/app/benchmark/source_brief.md')
SPEC = Path('/app/benchmark/task_input.json')
OUT = Path('/app/output/final_report.html')
OUT.parent.mkdir(parents=True, exist_ok=True)

