with open(SPEC) as f:
    spec = json.load(f)

def pct(x, digits=1):
    return f"{x*100:.{digits}f}%"

def money(x, digits=0):
    return f"${x:,.{digits}f}"

def num(x, digits=0):
    return f"{x:,.{digits}f}"

def dec(x, digits=2):
    return f"{x:.{digits}f}"

def esc(s):
    return html.escape(str(s), quote=True)

def svg_line(series, width=680, height=300, color='#2563eb', yfmt=lambda v: f'{v:.1f}', title='', area=False, extra_series=None):
    # series: list of (x,y,label)
    if extra_series is None: extra_series=[]
    all_values = [y for _, y, *_ in series]
    for es in extra_series:
        all_values += [y for _, y, *_ in es.get('series', [])]
    xmin, xmax = min(x for x, *_ in series), max(x for x, *_ in series)
    ymin, ymax = min(all_values), max(all_values)
    if math.isclose(ymin, ymax):
        ymin -= 1; ymax += 1
    pad = (ymax-ymin)*0.12
    ymin -= pad; ymax += pad
    ml, mr, mt, mb = 58, 18, 24, 46
    cw, ch = width-ml-mr, height-mt-mb
    def sx(x): return ml + (x-xmin)/(xmax-xmin)*cw
    def sy(y): return mt + (ymax-y)/(ymax-ymin)*ch
    yticks = [ymin + i*(ymax-ymin)/4 for i in range(5)]
    xticks = [2015,2020,2025,2030,2035]
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}" class="chart-svg">']
    parts.append('<rect width="100%" height="100%" fill="white" rx="14"/>')
    for y in yticks:
        parts.append(f'<line x1="{ml}" x2="{width-mr}" y1="{sy(y):.1f}" y2="{sy(y):.1f}" stroke="#e5e7eb"/>')
        parts.append(f'<text x="{ml-10}" y="{sy(y)+4:.1f}" text-anchor="end" class="axis">{esc(yfmt(y))}</text>')
    for x in xticks:
        parts.append(f'<text x="{sx(x):.1f}" y="{height-18}" text-anchor="middle" class="axis">{x}</text>')
    parts.append(f'<line x1="{ml}" x2="{width-mr}" y1="{height-mb}" y2="{height-mb}" stroke="#cbd5e1"/>')
    parts.append(f'<line x1="{ml}" x2="{ml}" y1="{mt}" y2="{height-mb}" stroke="#cbd5e1"/>')
    def path_for(s):
        return ' '.join(('M' if i==0 else 'L')+f' {sx(x):.1f} {sy(y):.1f}' for i,(x,y,*_) in enumerate(s))
    if area:
        d = path_for(series) + f' L {sx(series[-1][0]):.1f} {height-mb} L {sx(series[0][0]):.1f} {height-mb} Z'
        parts.append(f'<path d="{d}" fill="{color}" opacity="0.10"/>')
    parts.append(f'<path d="{path_for(series)}" fill="none" stroke="{color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>')
    for es in extra_series:
        parts.append(f'<path d="{path_for(es["series"])}" fill="none" stroke="{es.get("color", "#64748b")}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>')
    for x,y,*rest in series[::max(1,len(series)//6)]:
        parts.append(f'<circle cx="{sx(x):.1f}" cy="{sy(y):.1f}" r="3.5" fill="{color}"/>')
    # endpoints
    for s,c in [(series,color)] + [(es['series'], es.get('color','#64748b')) for es in extra_series]:
        for x,y,*_ in [s[0],s[-1]]:
            parts.append(f'<circle cx="{sx(x):.1f}" cy="{sy(y):.1f}" r="4" fill="white" stroke="{c}" stroke-width="2"/>')
            parts.append(f'<text x="{sx(x):.1f}" y="{sy(y)-8:.1f}" text-anchor="middle" class="point-label">{esc(yfmt(y))}</text>')
    parts.append('</svg>')
    return ''.join(parts)

def svg_bar(rows, label_key, value_key, width=680, height=320, color='#2563eb', yfmt=lambda v:f'{v:.0f}', title='', horizontal=True, max_items=None):
    if max_items: rows=rows[:max_items]
    ml, mr, mt, mb = (176, 24, 20, 34) if horizontal else (44, 20, 24, 74)
    cw, ch = width-ml-mr, height-mt-mb
    vals=[float(r[value_key]) for r in rows]
    vmax=max(vals) if vals else 1
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}" class="chart-svg">','<rect width="100%" height="100%" fill="white" rx="14"/>']
    if horizontal:
        gap=8; barh=(ch-gap*(len(rows)-1))/len(rows)
        for i,r in enumerate(rows):
            y=mt+i*(barh+gap); w=(float(r[value_key])/vmax)*cw
            parts.append(f'<text x="{ml-10}" y="{y+barh/2+4:.1f}" text-anchor="end" class="bar-label">{esc(r[label_key])}</text>')
            parts.append(f'<rect x="{ml}" y="{y:.1f}" width="{w:.1f}" height="{barh:.1f}" rx="5" fill="{color}" opacity="{0.92-i*0.025:.2f}"/>')
            parts.append(f'<text x="{ml+w+7:.1f}" y="{y+barh/2+4:.1f}" class="point-label">{esc(yfmt(float(r[value_key])))}</text>')
    else:
        gap=14; barw=(cw-gap*(len(rows)-1))/len(rows)
        for i,r in enumerate(rows):
            h=(float(r[value_key])/vmax)*ch; x=ml+i*(barw+gap); y=mt+ch-h
            parts.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{barw:.1f}" height="{h:.1f}" rx="5" fill="{color}"/>')
            parts.append(f'<text x="{x+barw/2:.1f}" y="{y-7:.1f}" text-anchor="middle" class="point-label">{esc(yfmt(float(r[value_key])))}</text>')
            parts.append(f'<text transform="translate({x+barw/2:.1f},{height-13}) rotate(-38)" text-anchor="end" class="axis">{esc(r[label_key])}</text>')
    parts.append('</svg>')
    return ''.join(parts)

def svg_scatter(rows, xkey, ykey, labelkey, width=680, height=360, title=''):
    xs=[float(r[xkey]) for r in rows]; ys=[float(r[ykey]) for r in rows]
    xmin,xmax=min(xs),max(xs); ymin,ymax=min(ys),max(ys)
    xpad=(xmax-xmin)*0.14; ypad=(ymax-ymin)*0.16
    xmin-=xpad; xmax+=xpad; ymin-=ypad; ymax+=ypad
    ml,mr,mt,mb=70,28,22,58; cw=width-ml-mr; ch=height-mt-mb
    def sx(x): return ml+(x-xmin)/(xmax-xmin)*cw
    def sy(y): return mt+(ymax-y)/(ymax-ymin)*ch
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}" class="chart-svg">','<rect width="100%" height="100%" fill="white" rx="14"/>']
    for i in range(5):
        y=ymin+i*(ymax-ymin)/4; x=xmin+i*(xmax-xmin)/4
        parts.append(f'<line x1="{ml}" x2="{width-mr}" y1="{sy(y):.1f}" y2="{sy(y):.1f}" stroke="#e5e7eb"/>')
        parts.append(f'<text x="{ml-10}" y="{sy(y)+4:.1f}" text-anchor="end" class="axis">{money(y/1000,0)}k</text>')
        parts.append(f'<text x="{sx(x):.1f}" y="{height-24}" text-anchor="middle" class="axis">{x:.2f}</text>')
    parts.append(f'<text x="{ml+cw/2}" y="{height-5}" text-anchor="middle" class="axis-title">Average AI risk score</text>')
    parts.append(f'<text transform="translate(18,{mt+ch/2}) rotate(-90)" text-anchor="middle" class="axis-title">Median salary</text>')
    colors=['#dc2626','#f59e0b','#2563eb','#0891b2','#16a34a','#7c3aed','#475569','#db2777','#0f766e','#ea580c']
    for i,r in enumerate(rows):
        parts.append(f'<circle cx="{sx(float(r[xkey])):.1f}" cy="{sy(float(r[ykey])):.1f}" r="8" fill="{colors[i%len(colors)]}" opacity="0.84"/>')
        dx=10 if i%2==0 else -10; anchor='start' if i%2==0 else 'end'
        parts.append(f'<text x="{sx(float(r[xkey]))+dx:.1f}" y="{sy(float(r[ykey]))-10:.1f}" text-anchor="{anchor}" class="scatter-label">{esc(r[labelkey])}</text>')
    parts.append('</svg>')
    return ''.join(parts)

