def table(headers, rows):
    h=''.join(f'<th>{esc(x)}</th>' for x in headers)
    body=''
    for row in rows:
        body += '<tr>' + ''.join(f'<td>{cell}</td>' for cell in row) + '</tr>'
    return f'<div class="table-wrap"><table><thead><tr>{h}</tr></thead><tbody>{body}</tbody></table></div>'

